# undershield_img($height_px) -> <img> tag with the logo at that height
sub undershield_img {
    my $h = shift || 20;
    my $uri = 'data:image/svg+xml;base64,' . MIME::Base64::encode_base64($UNDERSHIELD_SVG, '');
    return qq{<img src="$uri" alt="UnderShield" height="$h" style="height:${h}px;width:auto;display:block">};
}

1;
